draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.font = '48px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('1222', W/2, H/2);
  ctx.beginPath();
  ctx.arc(W/2 - 70, H/2 - 20, 10, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 + 70, H/2 - 20, 10, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 60, H/2 - 20);
  ctx.lineTo(W/2 - 60, H/2 + 20);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 60, H/2 - 20);
  ctx.lineTo(W/2 + 60, H/2 + 20);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2, H/2 + 50, 10, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.save();
  ctx.translate(W/2, H/2);
  ctx.rotate(Math.sin(t));
  ctx.beginPath();
  ctx.moveTo(-20, 0);
  ctx.lineTo(20, 0);
  ctx.stroke();
  ctx.restore();
  ctx.restore();
}
